<?php
/** UI design patterns: navigation, input and forms, feedback and status, data display. */

return [
    'id' => 'ui-patterns', 'family' => 'ui', 'after' => 'ui-base', 'categories' => ['design', 'frontend'],
    'title' => L('Pattern di interfaccia', 'UI Design Patterns'), 'short' => L('Pattern UI', 'UI Patterns'), 'level' => L('Intermedio', 'Intermediate'),
    'desc' => L('Le soluzioni ricorrenti delle interfacce: pattern di navigazione, di inserimento dati, di feedback e di visualizzazione dei dati, e quando usare ciascuno.', 'The recurring solutions of interfaces: navigation, data input, feedback and data display patterns, and when to use each.'),
    'lessons' => [
        lesson('navigation', L('Pattern di navigazione', 'Navigation patterns'), [
            P('Un **pattern** è una soluzione collaudata a un problema ricorrente: gli utenti lo riconoscono senza doverlo imparare. Per la navigazione: **barra in alto** con poche voci (siti), **barra laterale** (app con molte sezioni), **tab** per viste dello stesso contenuto, **breadcrumb** per mostrare dove sei in una gerarchia profonda, **paginazione** o **scroll infinito** per liste lunghe.', 'A **pattern** is a proven solution to a recurring problem: users recognise it without having to learn it. For navigation: a **top bar** with few items (websites), a **sidebar** (apps with many sections), **tabs** for views of the same content, **breadcrumbs** to show where you are in a deep hierarchy, **pagination** or **infinite scroll** for long lists.'),
            P('Lo **scroll infinito** va bene per contenuti da sfogliare (feed), meno per cercare qualcosa di preciso: si perde la posizione e il footer diventa irraggiungibile. La **paginazione** o un pulsante “Carica altri” danno controllo. Il **mega menu** mostra molte categorie in un pannello ampio, utile per i negozi online.', '**Infinite scroll** suits content to browse (feeds), less so searching for something specific: you lose your place and the footer becomes unreachable. **Pagination** or a “Load more” button give control. The **mega menu** shows many categories in a wide panel, useful for online shops.'),
        ], [
            Q('n1', L('Che cosa mostra un breadcrumb?', 'What does a breadcrumb show?'), [L('Dove sei in una gerarchia', 'Where you are in a hierarchy'), L('Le briciole del sito', 'The site’s crumbs'), L('Le notifiche', 'Notifications'), L('Il carrello', 'The cart')], 0, L('Home › Scarpe › Corsa.', 'Home › Shoes › Running.')),
            Q('n2', L('Quando lo scroll infinito è una cattiva scelta?', 'When is infinite scroll a bad choice?'), [L('Quando si cerca qualcosa di preciso', 'When looking for something specific'), L('In un feed social', 'In a social feed'), L('Per sfogliare foto', 'For browsing photos'), L('Mai', 'Never')], 0, L('Si perde la posizione.', 'You lose your place.')),
            Q('n3', L('A che cosa servono le tab?', 'What are tabs for?'), [L('Viste diverse dello stesso contenuto', 'Different views of the same content'), L('Aprire siti diversi', 'Opening different sites'), L('Mostrare errori', 'Showing errors'), L('Caricare file', 'Uploading files')], 0, L('Stesso livello, viste parallele.', 'Same level, parallel views.')),
        ], task('html', L('Scrivi un breadcrumb accessibile: un `<nav aria-label="Breadcrumb">` con una lista `<ol>` di tre voci, l’ultima con `aria-current="page"`.', 'Write an accessible breadcrumb: a `<nav aria-label="Breadcrumb">` with an `<ol>` list of three items, the last with `aria-current="page"`.'), '<nav>\n  \n</nav>', [has('nav[aria-label] ol', L('Nav con lista ordinata', 'Nav with ordered list')), has('nav ol li:nth-child(3)', L('Tre voci', 'Three items')), has('[aria-current="page"]', L('Pagina corrente indicata', 'Current page marked'))], '', "<nav aria-label=\"Breadcrumb\">\n  <ol>\n    <li><a href=\"/\">Home</a></li>\n    <li><a href=\"/scarpe\">Scarpe</a></li>\n    <li aria-current=\"page\">Corsa</li>\n  </ol>\n</nav>"), [
            dMatch(pMatch(), [['Breadcrumb', L('Posizione nella gerarchia', 'Position in the hierarchy')], [L('Tab', 'Tabs'), L('Viste dello stesso contenuto', 'Views of the same content')], [L('Scroll infinito', 'Infinite scroll'), L('Feed da sfogliare', 'Feeds to browse')], [L('Paginazione', 'Pagination'), L('Controllo sulla posizione', 'Control over position')], ['Mega menu', L('Molte categorie in un pannello', 'Many categories in a panel')]], L('Muoversi tra i contenuti.', 'Moving through content.')),
            dFlash(pFlash(), [[L('Un pattern noto non va imparato da capo', 'A known pattern need not be learned from scratch'), true], [L('Con lo scroll infinito il footer è sempre facile da raggiungere', 'With infinite scroll the footer is always easy to reach'), false], [L('Il breadcrumb aiuta nelle gerarchie profonde', 'Breadcrumbs help in deep hierarchies'), true], [L('Le tab servono per passare a un altro sito', 'Tabs are for going to another site'), false]], L('Pattern di navigazione.', 'Navigation patterns.')),
        ]),
        lesson('input', L('Pattern di inserimento', 'Input patterns'), [
            P('Scegliere il **controllo giusto** riduce gli errori: **radio** per una scelta tra poche opzioni visibili (2-5), **select** o **combobox** per molte, **checkbox** per scelte multiple o un sì/no da confermare, **interruttore** (switch) per un’impostazione che ha effetto subito, **stepper** per piccole quantità, **date picker** per le date (ma un campo testo per la data di nascita, che è lontana).', 'Choosing the **right control** reduces errors: **radio** buttons for one choice among few visible options (2-5), **select** or **combobox** for many, **checkbox** for multiple choices or a yes/no to confirm, a **switch** for a setting that takes effect immediately, a **stepper** for small quantities, a **date picker** for dates (but a text field for birth dates, which are far away).'),
            P('Per i moduli lunghi: **un modulo, una colonna**, raggruppa i campi correlati, usa un **wizard** a passi con indicatore di avanzamento, mostra la **validazione in linea** dopo che l’utente lascia il campo, e metti valori predefiniti sensati. Il **segnaposto** (placeholder) non sostituisce l’etichetta: sparisce mentre scrivi.', 'For long forms: **one form, one column**, group related fields, use a step-by-step **wizard** with a progress indicator, show **inline validation** after the user leaves a field, and set sensible defaults. The **placeholder** does not replace the label: it disappears while you type.'),
        ], [
            Q('i1', L('Quale controllo per scegliere una taglia tra S, M, L?', 'Which control to pick a size among S, M, L?'), [L('Radio', 'Radio buttons'), L('Campo di testo libero', 'Free text field'), L('Checkbox multiple', 'Multiple checkboxes'), L('Date picker', 'Date picker')], 0, L('Una scelta tra poche opzioni.', 'One choice among few options.')),
            Q('i2', L('Quando usare un interruttore (switch)?', 'When to use a switch?'), [L('Per un’impostazione con effetto immediato', 'For a setting with immediate effect'), L('Per accettare i termini al checkout', 'For accepting terms at checkout'), L('Per scegliere un paese', 'For choosing a country'), L('Per scrivere un testo', 'For writing text')], 0, L('Come accendere una luce.', 'Like flipping a light.')),
            Q('i3', L('Perché il placeholder non sostituisce l’etichetta?', 'Why does the placeholder not replace the label?'), [L('Sparisce mentre si scrive', 'It disappears while typing'), L('È troppo colorato', 'It is too colourful'), L('Non si può stilizzare', 'It cannot be styled'), L('Pesa troppo', 'It weighs too much')], 0, L('Poi non ricordi che campo era.', 'Then you forget what field it was.')),
        ], task('html', L('Per scegliere la consegna tra “Standard” ed “Express” usa due `<input type="radio">` con lo stesso `name="consegna"` e ciascuno con la sua `<label>`.', 'To choose delivery between “Standard” and “Express” use two `<input type="radio">` with the same `name="consegna"`, each with its own `<label>`.'), '<fieldset>\n  <legend>Consegna</legend>\n  \n</fieldset>', [has('input[type="radio"][name="consegna"] ~ input[type="radio"][name="consegna"], label input[type="radio"][name="consegna"]', L('Due radio con lo stesso name', 'Two radios with the same name')), re('(<label[^>]*>[^<]*<input[^>]*type="radio"[\s\S]*){2}|(<input[^>]*type="radio"[^>]*id="[^"]+"[\s\S]*<label[^>]*for=[\s\S]*){2}', L('Ogni radio ha un’etichetta', 'Each radio has a label'))], '', "<label><input type=\"radio\" name=\"consegna\" checked> Standard</label>\n<label><input type=\"radio\" name=\"consegna\"> Express</label>"), [
            dMatch(pMatch(), [['Radio', L('Una scelta tra poche', 'One choice among few')], ['Select', L('Una scelta tra molte', 'One choice among many')], ['Checkbox', L('Scelte multiple', 'Multiple choices')], ['Switch', L('Effetto immediato', 'Immediate effect')], ['Stepper', L('Piccole quantità', 'Small quantities')]], L('Il controllo giusto.', 'The right control.')),
            dFlash(pFlash(), [[L('Un modulo a una colonna si compila più facilmente', 'A one-column form is easier to fill in'), true], [L('Il placeholder basta come etichetta', 'The placeholder is enough as a label'), false], [L('La validazione in linea aiuta a correggere subito', 'Inline validation helps fix things at once'), true], [L('Per la data di nascita il calendario è sempre il migliore', 'For birth dates a calendar is always best'), false]], L('Inserire dati senza fatica.', 'Entering data effortlessly.')),
        ]),
        lesson('feedback', L('Pattern di feedback', 'Feedback patterns'), [
            P('L’interfaccia deve sempre rispondere. Per durate diverse servono feedback diversi: sotto 1 secondo basta un cambio di stato del pulsante; da 1 a 10 secondi uno **spinner** o uno **skeleton**; oltre, una **barra di avanzamento** con stima e la possibilità di annullare. Le **conferme** brevi usano toast o snackbar, gli **avvisi** persistenti usano banner.', 'The interface must always respond. Different durations need different feedback: under 1 second a button state change is enough; from 1 to 10 seconds a **spinner** or **skeleton**; beyond that, a **progress bar** with an estimate and the option to cancel. Brief **confirmations** use toasts or snackbars, persistent **warnings** use banners.'),
            P('Per le azioni distruttive ci sono due strade: la **finestra di conferma** (“Eliminare 12 foto?” con il pulsante che ripete l’azione: “Elimina 12 foto”) oppure, spesso migliore, l’**annulla** dopo l’azione. L’**interfaccia ottimista** mostra subito il risultato (il “mi piace” si colora) e sincronizza dietro le quinte, tornando indietro solo in caso di errore.', 'For destructive actions there are two paths: the **confirmation dialog** (“Delete 12 photos?” with a button repeating the action: “Delete 12 photos”) or, often better, **undo** after the action. The **optimistic UI** shows the result immediately (the “like” turns coloured) and syncs behind the scenes, rolling back only on error.'),
        ], [
            Q('f1', L('Che feedback per un’operazione di 30 secondi?', 'What feedback for a 30-second operation?'), [L('Barra di avanzamento con possibilità di annullare', 'Progress bar with a cancel option'), L('Nessuno', 'None'), L('Solo un cambio di colore', 'Just a colour change'), L('Un suono alla fine', 'A sound at the end')], 0, L('Lunghe attese, più informazioni.', 'Long waits, more information.')),
            Q('f2', L('Che testo dare al pulsante di una conferma di eliminazione?', 'What text for a delete confirmation button?'), [L('Elimina 12 foto', 'Delete 12 photos'), 'OK', L('Sì', 'Yes'), L('Continua', 'Continue')], 0, L('Ripeti l’azione.', 'Repeat the action.')),
            Q('f3', L('Che cos’è un’interfaccia ottimista?', 'What is an optimistic UI?'), [L('Mostra subito il risultato e sincronizza dopo', 'Shows the result at once and syncs later'), L('Un’interfaccia sempre sorridente', 'An always-smiling interface'), L('Un’interfaccia senza errori possibili', 'An interface where errors are impossible'), L('Un tema giallo', 'A yellow theme')], 0, L('Torna indietro solo se fallisce.', 'It rolls back only on failure.')),
        ], task('text', L('Scegli il feedback per tre durate, una riga ciascuna nel formato `durata: feedback`: `0,3 s`, `4 s`, `2 min`.', 'Pick the feedback for three durations, one line each in the format `duration: feedback`: `0.3 s`, `4 s`, `2 min`.'), "0,3 s: \n4 s: \n2 min: ", [re('^0[,.]3\s*s\s*:\s*.*(stato|state|pulsante|button|colore|colou?r|nessun)', L('Basta il cambio di stato', 'A state change is enough')), re('^4\s*s\s*:\s*.*(spinner|skeleton|rotell|caricamento|loading)', L('Uno spinner o skeleton', 'A spinner or skeleton')), re('^2\s*min\s*:\s*.*(barra|progress|avanzamento)', L('Una barra di avanzamento', 'A progress bar'))], '', "0,3 s: cambio di stato del pulsante\n4 s: spinner\n2 min: barra di avanzamento con Annulla"), [
            dOrder(pSort(), [L('Cambio di stato del pulsante', 'Button state change'), 'Spinner', 'Skeleton screen', L('Barra di avanzamento con stima', 'Progress bar with estimate')], L('Dall’attesa più breve alla più lunga.', 'From shortest to longest wait.')),
            dFlash(pFlash(), [[L('L’annulla è spesso migliore di una conferma', 'Undo is often better than a confirmation'), true], [L('Un pulsante “OK” chiarisce un’eliminazione', 'An “OK” button clarifies a deletion'), false], [L('Un banner va bene per un avviso persistente', 'A banner suits a persistent warning'), true], [L('Le attese lunghe non hanno bisogno di feedback', 'Long waits need no feedback'), false]], L('Rispondere sempre.', 'Always responding.')),
        ]),
        lesson('data', L('Pattern per i dati', 'Data display patterns'), [
            P('Per mostrare insiemi di dati: le **tabelle** sono ideali per confrontare molti attributi (ordinamento per colonna, numeri allineati a destra, intestazione fissa), le **card** per elementi visivi e eterogenei (prodotti, articoli), le **liste** per scorrere elementi simili. Su telefono una tabella larga si trasforma spesso in card o in lista con i dati principali.', 'To display data sets: **tables** are ideal for comparing many attributes (sorting by column, right-aligned numbers, sticky header), **cards** for visual, heterogeneous items (products, articles), **lists** for scrolling similar items. On phones a wide table often turns into cards or a list with the main data.'),
            P('Per trovare: **ricerca** con suggerimenti, **filtri** (a faccette nei negozi, con il numero di risultati e i filtri attivi ben visibili e rimovibili), **ordinamento**. Per riassumere: **dashboard** con pochi indicatori chiave in alto e il dettaglio sotto. La regola di Shneiderman: **prima la panoramica, poi zoom e filtri, poi i dettagli su richiesta**.', 'To find: **search** with suggestions, **filters** (faceted in shops, with result counts and active filters clearly visible and removable), **sorting**. To summarise: **dashboards** with a few key indicators at the top and detail below. Shneiderman’s mantra: **overview first, zoom and filter, then details on demand**.'),
        ], [
            Q('d1', L('Quando una tabella è la scelta migliore?', 'When is a table the best choice?'), [L('Per confrontare molti attributi', 'To compare many attributes'), L('Per mostrare foto di prodotti', 'To show product photos'), L('Per un solo valore', 'For a single value'), L('Mai su desktop', 'Never on desktop')], 0, L('Colonne confrontabili.', 'Comparable columns.')),
            Q('d2', L('Come si allineano i numeri in una tabella?', 'How are numbers aligned in a table?'), [L('A destra', 'Right'), L('Al centro', 'Centre'), L('A sinistra', 'Left'), L('A caso', 'Randomly')], 0, L('Le cifre si confrontano in colonna.', 'Digits compare in a column.')),
            Q('d3', L('Che cosa dice il mantra di Shneiderman?', 'What does Shneiderman’s mantra say?'), [L('Panoramica, zoom e filtri, dettagli su richiesta', 'Overview, zoom and filter, details on demand'), L('Dettagli prima di tutto', 'Details first'), L('Mai filtrare', 'Never filter'), L('Una tabella per ogni dato', 'One table per datum')], 0, L('Dal generale al particolare.', 'From general to specific.')),
        ], task('css', L('Allinea a destra i numeri della colonna `.importo` con `text-align: right` e usa cifre a larghezza fissa con `font-variant-numeric: tabular-nums`.', 'Right-align the numbers in the `.importo` column with `text-align: right` and use fixed-width digits with `font-variant-numeric: tabular-nums`.'), "td {\n  padding: 8px;\n}\n", [css('.importo', 'text-align', 'right', L('Numeri a destra', 'Numbers on the right')), re('\.importo\s*\{[^}]*font-variant-numeric\s*:\s*tabular-nums', L('Cifre tabulari', 'Tabular digits'))], "<table>\n  <tr><td>Affitto</td><td class=\"importo\">1.200,00</td></tr>\n  <tr><td>Luce</td><td class=\"importo\">87,50</td></tr>\n</table>", ".importo {\n  text-align: right;\n  font-variant-numeric: tabular-nums;\n}"), [
            dMatch(pMatch(), [[L('Tabella', 'Table'), L('Confronto di attributi', 'Comparing attributes')], ['Card', L('Elementi visivi diversi', 'Varied visual items')], [L('Filtri a faccette', 'Faceted filters'), L('Restringere i risultati', 'Narrowing results')], ['Dashboard', L('Indicatori chiave', 'Key indicators')], ['tabular-nums', L('Cifre allineate', 'Aligned digits')]], L('Mostrare i dati.', 'Showing data.')),
            dFlash(pFlash(), [[L('I filtri attivi devono essere visibili e rimovibili', 'Active filters should be visible and removable'), true], [L('Su telefono una tabella larga va sempre lasciata così', 'On phones a wide table should always stay as is'), false], [L('Una dashboard mette in alto pochi indicatori chiave', 'A dashboard puts a few key indicators at the top'), true], [L('I numeri si leggono meglio centrati', 'Numbers read better centred'), false]], L('Dati chiari.', 'Clear data.')),
        ]),
    ],
];
